(function(){'use strict';const RM=window.matchMedia('(prefers-reduced-motion: reduce)').matches;const API='https://api.aallyn.net';requestAnimationFrame(()=>requestAnimationFrame(()=>{document.body.classList.add('ready');}));const navbar=document.querySelector('.navbar');if(navbar){let ticking=false;const update=()=>{navbar.classList.toggle('scrolled',window.scrollY>40);ticking=false;};window.addEventListener('scroll',()=>{if(!ticking){requestAnimationFrame(update);ticking=true;}},{passive:true});update();}
if('IntersectionObserver'in window){const io=new IntersectionObserver((entries)=>{for(const e of entries){if(e.isIntersecting){e.target.classList.add('in-view');io.unobserve(e.target);}}},{rootMargin:'0px 0px -10% 0px',threshold:0.15});document.querySelectorAll('.spotlight, .bento-tile').forEach(el=>io.observe(el));}else{document.querySelectorAll('.spotlight, .bento-tile').forEach(el=>el.classList.add('in-view'));}
if('IntersectionObserver'in window){const statIO=new IntersectionObserver((entries)=>{for(const e of entries){if(!e.isIntersecting)continue;const el=e.target;const target=parseInt(el.dataset.target,10);statIO.unobserve(el);if(!Number.isFinite(target))continue;if(RM){el.textContent=target.toLocaleString();continue;}
const start=performance.now();const dur=1400;const ease=t=>1-Math.pow(1-t,3);const tick=(now)=>{const t=Math.min(1,(now-start)/dur);el.textContent=Math.round(target*ease(t)).toLocaleString();if(t<1)requestAnimationFrame(tick);};requestAnimationFrame(tick);}},{threshold:0.4});document.querySelectorAll('.stat-num[data-target]').forEach(el=>statIO.observe(el));}
(async()=>{const slot=document.querySelector('.hero-screens');if(!slot)return;let urls=[];try{const r=await fetch('/site/screenshots.json',{cache:'default'});if(!r.ok)throw new Error('HTTP '+r.status);const data=await r.json();urls=Array.isArray(data.screenshots)?data.screenshots:[];}catch(e){console.warn('[landing] screenshot list fetch failed:',e.message);return;}
if(urls.length===0)return;const imgs=urls.map(src=>{const i=document.createElement('img');i.src=src;i.alt='';i.loading='eager';i.decoding='async';slot.appendChild(i);return i;});requestAnimationFrame(()=>imgs[0].classList.add('active'));if(RM||imgs.length===1)return;let cur=0;const PERIOD=8000;const advance=()=>{const next=(cur+1)%imgs.length;imgs[next].classList.add('active');imgs[cur].classList.remove('active');cur=next;};let timer=setInterval(advance,PERIOD);document.addEventListener('visibilitychange',()=>{if(document.hidden){clearInterval(timer);timer=null;}
else if(!timer){timer=setInterval(advance,PERIOD);}});})();try{const canvas=document.querySelector('canvas.bg-fx');if(canvas&&!RM){const ctx=canvas.getContext('2d',{alpha:true});if(ctx){const dpr=Math.min(window.devicePixelRatio||1,2);let parts=[];let w=0,h=0,rafId=null;const seed=()=>{const count=Math.min(80,Math.floor((w*h)/22000));parts=Array.from({length:count},()=>({x:Math.random()*w,y:Math.random()*h,vx:(Math.random()-0.5)*0.06,vy:(Math.random()-0.5)*0.08-0.04,r:Math.random()*1.4+0.4,a:Math.random()*0.4+0.15,}));};const resize=()=>{w=window.innerWidth;h=window.innerHeight;canvas.width=Math.floor(w*dpr);canvas.height=Math.floor(h*dpr);ctx.setTransform(dpr,0,0,dpr,0,0);seed();};const tick=()=>{ctx.clearRect(0,0,w,h);ctx.fillStyle='rgba(120, 180, 255, 1)';for(const p of parts){p.x+=p.vx;p.y+=p.vy;if(p.x<-5)p.x=w+5;else if(p.x>w+5)p.x=-5;if(p.y<-5)p.y=h+5;else if(p.y>h+5)p.y=-5;ctx.globalAlpha=p.a;ctx.beginPath();ctx.arc(p.x,p.y,p.r,0,Math.PI*2);ctx.fill();}
ctx.globalAlpha=1;rafId=requestAnimationFrame(tick);};const start=()=>{if(rafId===null)rafId=requestAnimationFrame(tick);};const stop=()=>{if(rafId!==null){cancelAnimationFrame(rafId);rafId=null;}};window.addEventListener('resize',()=>{resize();},{passive:true});document.addEventListener('visibilitychange',()=>{if(document.hidden)stop();else start();});resize();start();}}}catch(e){console.warn('[landing] canvas fx disabled:',e&&e.message);}
const $live=(key)=>document.querySelector(`[data-live="${key}"]`);const cards={serverTime:document.querySelector('[data-live="server-time-card"]'),troveDay:document.querySelector('[data-live="trove-day-card"]'),chaos:document.querySelector('[data-live="chaos-card"]'),challenge:document.querySelector('[data-live="challenge-card"]'),};const fields={serverTime:$live('server-time'),serverDate:$live('server-date'),troveDay:$live('trove-day'),resetIn:$live('reset-in'),chaosName:$live('chaos-name'),chaosEnds:$live('chaos-ends'),challName:$live('challenge-name'),challKind:$live('challenge-kind'),};let serverEpochOffset=null;let dailyResetAt=null;function fmtClock(date){const pad=n=>String(n).padStart(2,'0');return`${pad(date.getUTCHours())}:${pad(date.getUTCMinutes())}:${pad(date.getUTCSeconds())}`;}
function fmtCountdown(seconds){if(seconds<=0)return'-';const h=Math.floor(seconds/3600);const m=Math.floor((seconds%3600)/60);if(h>0)return`${h}h ${m}m`;return`${m}m`;}
function flash(card){if(!card)return;card.classList.remove('flash');void card.offsetWidth;card.classList.add('flash');}
function tickClock(){if(fields.serverTime&&serverEpochOffset!==null){const now=new Date(performance.now()+serverEpochOffset);fields.serverTime.textContent=fmtClock(now);if(fields.serverDate){fields.serverDate.textContent=now.toUTCString().slice(5,16)+' UTC';}
if(dailyResetAt){const left=dailyResetAt-Math.floor(now.getTime()/1000);if(fields.resetIn)fields.resetIn.textContent=`daily reset in ${fmtCountdown(left)}`;}}
requestAnimationFrame(tickClock);}
requestAnimationFrame(tickClock);async function safeFetch(path){try{const ctrl=new AbortController();const t=setTimeout(()=>ctrl.abort(),8000);const r=await fetch(API+path,{signal:ctrl.signal});clearTimeout(t);if(!r.ok)throw new Error(`HTTP ${r.status}`);return await r.json();}catch(e){if(!safeFetch._warned){console.warn('[landing] live data fetch failed:',e.message);safeFetch._warned=true;}
return null;}}
async function refreshLive(){const[time,chaos,challenge]=await Promise.all([safeFetch('/v1/rotations/server-time'),safeFetch('/v1/rotations/chaos-chest'),safeFetch('/v1/rotations/challenge/current'),]);if(time&&typeof time.now_unix==='number'){serverEpochOffset=time.now_unix*1000-performance.now();dailyResetAt=time.daily_reset_at||null;if(fields.troveDay&&time.trove_day){const prev=fields.troveDay.textContent;fields.troveDay.textContent=time.trove_day;if(prev&&prev!==time.trove_day)flash(cards.troveDay);}}
if(chaos){const name=(chaos.item&&chaos.item.name)||'Unknown';const prev=fields.chaosName?fields.chaosName.textContent:'';if(fields.chaosName)fields.chaosName.textContent=name;if(fields.chaosEnds&&typeof chaos.seconds_remaining==='number'){const days=Math.max(0,Math.floor(chaos.seconds_remaining/86400));fields.chaosEnds.textContent=days>0?`${days} day${days === 1 ? '' : 's'} left`:'rotates today';}
if(prev&&prev!==name&&prev!=='loading…')flash(cards.chaos);}
if(challenge){const name=challenge.name||'No active challenge';const prev=fields.challName?fields.challName.textContent:'';if(fields.challName)fields.challName.textContent=name;if(fields.challKind){if(challenge.type){const cap=challenge.type.charAt(0).toUpperCase()+challenge.type.slice(1);const left=typeof challenge.seconds_remaining==='number'&&challenge.active?`${cap} · ${Math.max(0, Math.floor(challenge.seconds_remaining / 60))}m left`:cap;fields.challKind.textContent=left;}else{fields.challKind.textContent='waiting for next window';}}
if(prev&&prev!==name&&prev!=='loading…')flash(cards.challenge);}}
const $status=document.getElementById('trove-status');const $statusText=$status&&$status.querySelector('.trove-status-text');const tr=(s)=>(window.BTTi18n&&window.BTTi18n.t?window.BTTi18n.t(s):s);function paintStatus(data){if(!$status||!$statusText)return;const overall=(data&&data.overall)||'unknown';if(overall==='unknown'){$status.hidden=true;return;}
let cls,label,title;if(overall==='down'){cls='is-down';label=tr('Offline');title=tr('The Trove login servers are unreachable.');}else if(overall==='maintenance'){cls='is-maint';label=tr('Maintenance');title=tr('Login works but the game servers are refusing connections.');}else{cls='is-up';label=tr('Online');title=tr('Trove login and game servers are responding.');}
$status.classList.remove('is-up','is-maint','is-down');$status.classList.add(cls);$statusText.textContent=label;$status.title=title;$status.hidden=false;}
async function refreshStatus(){try{const ctrl=new AbortController();const tm=setTimeout(()=>ctrl.abort(),8000);const r=await fetch('/site/trove-status',{signal:ctrl.signal});clearTimeout(tm);if(!r.ok)throw new Error(`HTTP ${r.status}`);paintStatus(await r.json());}catch(_){}}
const kick=()=>{refreshLive();refreshStatus();};if('requestIdleCallback'in window){requestIdleCallback(kick,{timeout:1500});}else{setTimeout(kick,300);}
setInterval(refreshLive,30_000);setInterval(refreshStatus,60_000);document.addEventListener('visibilitychange',()=>{if(!document.hidden){refreshLive();refreshStatus();}});})();